        }
        timeline.showTrackMix(track)
    }

    // MARK: - Validation

    /// The half of `validateUserInterfaceItem` this file owns. nil means "not
    /// mine" and leaves the other answers alone.
    func validateIdentityAction(
        _ action: Selector, item: any NSValidatedUserInterfaceItem
    ) -> Bool? {
        guard let document = document else { return false }
        switch action {
        case #selector(renameClip(_:)):
            return !document.selection.isEmpty
        case #selector(setClipLabel(_:)):
            if let menuItem = item as? NSMenuItem {
                let labels = ClipLabel.allCases
                let tagged: String? =
                    labels.indices.contains(menuItem.tag) ? labels[menuItem.tag].rawValue : nil
                menuItem.state = sharedClipLabel == .some(tagged) ? .on : .off
            }
            return !document.selection.isEmpty
        case #selector(toggleTrackSolo(_:)):
            // A checkmark, unlike its three siblings: solo is a mixing state
            // the ear cannot always confirm — a soloed track with nothing on
            // it still silences the rest — so the menu says which it is.
            let track = currentTrack
            (item as? NSMenuItem)?.state = track?.solo == true ? .on : .off
            return track != nil
        case #selector(setTrackMatte(_:)):
            // Track ▸ Matte's rows (spec §11 MT-7): the current track's mode
            // checked, by the row's tag.
            let track = currentTrack
            if let menuItem = item as? NSMenuItem {
                let modes = TrackMatte.allCases
                menuItem.state =
                    modes.indices.contains(menuItem.tag) && track?.matte == modes[menuItem.tag]
                    ? .on : .off
            }
            return track != nil
        case #selector(showTrackMix(_:)):
            return currentTrack != nil
        default:
            return nil
        }
    }

    /// The four header toggles as edits — one `set_track` flipping one flag —
    /// and the fifth switch, which opens the track's mix popover instead.
    func toggle(_ button: TimelineHeaderButton, on track: TrackSnapshot) {
        switch button {
        case .hidden:
            onEdit?("Hide Track", [.setTrack(track: track.id, hidden: !track.hidden)])
        case .muted:
            onEdit?("Mute Track", [.setTrack(track: track.id, muted: !track.muted)])
        case .locked:
            onEdit?("Lock Track", [.setTrack(track: track.id, locked: !track.locked)])
        case .solo:
            onEdit?("Solo Track", [.setTrack(track: track.id, solo: !track.solo)])
        case .mix:
            showTrackMix(track)
        }
    }

